int ext4_orphan_del(handle_t *handle, struct inode *inode) {
    struct ext4_inode_info *ei = EXT4_I(inode);
    struct ext4_iloc iloc;
    struct ext4_super_block *es = EXT4_SB(inode->i_sb)->s_es;
    int err = 0;
    int has_transaction = 0;
    __u32 hash;

    if (!ext4_has_feature_orphan(inode->i_sb))
        return 0;

    mutex_lock(&EXT4_SB(inode->i_sb)->s_orphan_lock);

    hash = ext4_inode_hash(inode);
    if (!hlist_empty(&ei->i_orphan))
        hlist_del_init(&ei->i_orphan);

    if (handle) {
        err = ext4_journal_start(handle, inode->i_sb, 1);
        if (err) {
            mutex_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
            return err;
        }
        has_transaction = 1;
    }

    err = ext4_reserve_inode_write(inode, handle, &iloc);
    if (err) {
        if (has_transaction)
            ext4_journal_stop(handle);
        mutex_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
        return err;
    }

    EXT4_I(inode)->i_dtime = 0;
    err = ext4_mark_inode_dirty(handle, inode, &iloc);
    if (err) {
        ext4_free_inode(handle, inode);
        if (has_transaction)
            ext4_journal_stop(handle);
        mutex_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
        return err;
    }

    if (has_transaction)
        ext4_journal_stop(handle);

    mutex_unlock(&EXT4_SB(inode->i_sb)->s_orphan_lock);
    return 0;
}

