    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    struct ext4_orphan *o;
    int err = 0;

    if (!ext4_has_feature_orphan(inode->i_sb))
        return 0;

    mutex_lock(&sbi->s_orphan_mutex);

    o = ext4_find_orphan(inode->i_ino);
    if (!o) {
        mutex_unlock(&sbi->s_orphan_mutex);
        return -ENOENT;
    }

    list_del(&o->o_list);
    kfree(o);

    if (handle) {
        err = ext4_journal_dirty_handle(handle, &sbi->s_orphan_head, NULL);
        if (err) {
            mutex_unlock(&sbi->s_orphan_mutex);
            return err;
        }
    }

    mutex_unlock(&sbi->s_orphan_mutex);
    return 0;
}

