    struct ext4_sb_info *sbi = EXT4_SB(inode->i_sb);
    struct ext4_orphan_list *orphan;
    int ret = 0;

    if (!sbi->s_journal)
        return 0;

    orphan = &sbi->s_orphan;

    mutex_lock(&orphan->lock);

    if (!list_empty(&ei->i_orphan))
        list_del_init(&ei->i_orphan);
    else {
        mutex_unlock(&orphan->lock);
        return -ENOENT;
    }

    mutex_unlock(&orphan->lock);

    if (handle)
        ret = ext4_mark_inode_dirty(handle, inode);

    return ret;
