    struct ext4_orphan *o;
    int err = 0;

    if (!sbi->s_journal)
        return 0;

    lock_orphan_list(sbi);

    o = find_orphan(inode->i_ino, sbi);
    if (!o) {
        unlock_orphan_list(sbi);
        return -ENOENT;
